    #gacha-no-event-text { font-family: var(--font-header); font-size: clamp(2.5em, 8vw, 5em); color: var(--color-gold); text-shadow: 0 0 10px var(--color-gold), 0 0 20px var(--color-gold); animation: star-glow 3s infinite alternate; }
    #gacha-viewer-fullscreen-btn { position: absolute; top: 20px; right: 20px; z-index: 10; width: 35px; height: 35px; background: rgba(0,0,0,0.5); color: white; border: 1px solid rgba(255,255,255,0.3); border-radius: 50%; display: flex; align-items: center; justify-content: center; font-size: 1.2em; cursor: pointer; transition: all 0.2s; pointer-events: auto; line-height: 1; }
    #gacha-viewer-fullscreen-btn:hover { background: rgba(255,255,255,0.2); }
    /* ===== GACHA UI END ===== */

    #galgame-container { position: absolute; top: 0; left: 0; width: 100%; height: 100%; font-family: var(--font-body); color: white; z-index: 800; cursor: pointer; user-select: none; -webkit-user-select: none; transition: opacity 0.5s, visibility 0.5s; opacity: 0; visibility: hidden; pointer-events: none; }
    #galgame-container.visible { opacity: 1; visibility: visible; pointer-events: auto; }
    #galgame-bg { position: absolute; top: 0; left: 0; width: 100%; height: 100%; background-size: cover; background-position: center; transition: background-image 1s ease-in-out; }
    #galgame-bg::after { content: ''; position: absolute; top: 0; left: 0; width: 100%; height: 100%; background: linear-gradient(to top, rgba(0,0,0,0.8) 20%, rgba(0,0,0,0.2) 60%, rgba(0,0,0,0.8) 100%); }
    #galgame-sprites { position: absolute; bottom: 0; left: 0; width: 100%; height: 100%; pointer-events: none; }
    .galgame-sprite { position: absolute; bottom: 0; height: 95%; max-width: 50%; object-fit: contain; object-position: center bottom; transition: opacity 0.4s ease-in-out, transform 0.5s cubic-bezier(0.25, 1, 0.5, 1), filter 0.4s; opacity: 0; filter: drop-shadow(2px 2px 10px rgba(0,0,0,0.7)); }
    #sprite-left { left: 25%; transform: translateX(-50%); }
    #sprite-right { right: 25%; transform: translateX(50%); }
    .galgame-sprite.visible { opacity: 0.85; filter: brightness(0.7) drop-shadow(2px 2px 10px rgba(0,0,0,0.7)); transform: translateX(0); }
    .galgame-sprite.active { opacity: 1; filter: brightness(1) drop-shadow(2px 2px 15px rgba(255,255,255,0.2)); transform: translateX(0) scale(1.02); }
    #dialogue-box { position: absolute; bottom: 4%; left: 50%; transform: translateX(-50%); width: 90%; max-width: 1200px; height: 28%; background: linear-gradient(to top, rgba(10, 25, 20, 0.95), rgba(15, 35, 30, 0.85)); backdrop-filter: blur(5px); -webkit-backdrop-filter: blur(5px); border-top: 2px solid var(--color-gold); border-radius: 4px; padding: 1.2em 2em; box-sizing: border-box; display: flex; flex-direction: column; box-shadow: 0 0 20px var(--color-shadow); }
    #speaker-name { font-family: var(--font-header); font-size: clamp(1.2em, 2.5vw, 1.8em); color: var(--color-gold); text-shadow: 1px 1px 3px #000; padding: 0.2em 0.8em; background: rgba(0,0,0,0.3); border-radius: 4px; align-self: flex-start; margin-bottom: 0.8em; }
    #dialogue-text { font-size: clamp(1em, 2vw, 1.4em); line-height: 1.6; flex-grow: 1; overflow-y: auto; color: var(--color-text-light); text-shadow: 1px 1px 2px #000; }
    #galgame-ui-controls { position: absolute; bottom: 5%; right: 2%; display: flex; flex-direction: column; gap: 10px; z-index: 810; }
    .galgame-ui-button { width: 35px; height: 35px; background: rgba(0,0,0,0.5); color: white; border: 1px solid rgba(255,255,255,0.3); border-radius: 50%; display: flex; align-items: center; justify-content: center; font-size: 1.2em; cursor: pointer; transition: background 0.2s, color 0.2s, box-shadow 0.2s; pointer-events: auto; line-height: 1; }
    .galgame-ui-button:hover { background: rgba(255,255,255,0.2); }
    #galgame-autoplay-btn.playing { color: #27ae60; box-shadow: 0 0 8px #27ae60; }
    #galgame-history-log { position: absolute; top: 0; left: 0; width: 100%; height: 100%; background: rgba(0,0,0,0.85); backdrop-filter: blur(4px); -webkit-backdrop-filter: blur(4px); z-index: 820; padding: 5%; box-sizing: border-box; opacity: 0; visibility: hidden; transition: opacity 0.3s, visibility 0.3s; overflow-y: auto; color: #ddd; }
    #galgame-history-log.visible { opacity: 1; visibility: visible; }
    .history-entry { margin-bottom: 1.2em; }
    .history-speaker { font-family: var(--font-header); color: var(--color-gold); margin-bottom: 0.3em; font-size: 1.3em; }
    .history-text { font-size: 1.1em; line-height: 1.6; padding-left: 1em; border-left: 2px solid var(--color-border); }
    #galgame-history-log::-webkit-scrollbar { width: 8px; }
    #galgame-history-log::-webkit-scrollbar-track { background: rgba(255,255,255,0.1); }
    #galgame-history-log::-webkit-scrollbar-thumb { background: var(--color-gold); }

    /* ===== CHARACTER RECORD (XIUXING LU) UI REDESIGN START ===== */
    @keyframes realm-pulse { 
        0%, 100% { box-shadow: 0 0 25px 5px var(--realm-color, transparent), inset 0 0 15px 2px var(--realm-color, transparent); }
        50% { box-shadow: 0 0 40px 10px var(--realm-color, transparent), inset 0 0 20px 4px var(--realm-color, transparent); }
    }
    #character-modal .modal-content {
        width: 90vw; height: 85vh;
        background: radial-gradient(ellipse at center, rgba(20, 15, 25, 0.95) 0%, rgba(5, 3, 8, 0.98) 100%);
        border-color: #4a2f58;
    }
    #character-modal .modal-body { display: flex; gap: 20px; padding: 20px; }
    .cultivation-record-layout { display: contents; } /* Use contents to integrate directly into flex */
    #cultivation-path {
        flex: 1;
        display: flex; flex-direction: column;
        align-items: center; gap: 10px;
        padding: 20px; overflow-y: auto;
    }
    #cultivation-path::-webkit-scrollbar { display: none; }
    .realm-card {
        background: rgba(10,10,10,0.4); border: 1px solid rgba(255,255,255,0.2);
        padding: 8px 15px; border-radius: 8px; width: 80%;
        text-align: center; transition: all 0.5s; color: rgba(255,255,255,0.4);
        position: relative;
    }
    .realm-card::before { /* Connection line */
        content: ''; position: absolute; left: 50%; top: -10px;
        width: 2px; height: 10px; background-color: rgba(255,255,255,0.2);
    }
    .realm-card:first-child::before { display: none; }
    .realm-card h3 { margin: 0; font-size: 1.2em; }
    .realm-card p { margin: 5px 0 0; font-size: 0.9em; }
    .realm-card.past-realm { border-color: var(--color-gold); color: var(--color-text-main); }
    .realm-card.past-realm::before { background-color: var(--color-gold); }
    .realm-card.future-realm { opacity: 0.6; filter: blur(1px); }
    .realm-card.current-realm {
        width: 100%; padding: 20px; color: white;
        transform: scale(1.1);
        border-width: 2px;
        border-color: var(--realm-color);
        animation: realm-pulse 4s infinite ease-in-out;
    }
    .realm-card.current-realm h3 { font-size: 2.2em; }
    .realm-card.current-realm p { font-size: 1.5em; color: var(--color-gold); }
    .realm-card.realm-fanren { --realm-color: var(--realm-fanren); }
    .realm-card.realm-lianqi { --realm-color: var(--realm-lianqi); }
    .realm-card.realm-zhuji { --realm-color: var(--realm-zhuji); }
    .realm-card.realm-jindan { --realm-color: var(--realm-jindan); }
    .realm-card.realm-yuanying { --realm-color: var(--realm-yuanying); }
    .realm-card.realm-huashen { --realm-color: var(--realm-huashen); }
    .realm-card.realm-fanxu { --realm-color: var(--realm-fanxu); }
    .realm-card.realm-hedao { --realm-color: var(--realm-hedao); }
    .realm-card.realm-dacheng { --realm-color: var(--realm-dacheng); }
    .realm-card.realm-dujie { --realm-color: var(--realm-dujie); }
    .realm-card.realm-xian { --realm-color: var(--realm-xian); }
    #dao-records {
        flex: 1; background: rgba(0,0,0,0.3); border-radius: 8px;
        padding: 0; display: flex; flex-direction: column;
    }
    .cr-tabs { display: flex; border-bottom: 1px solid var(--color-border); }
    .cr-tab {
        flex: 1; text-align: center; padding: 12px 0;
        font-family: var(--font-header); font-size: 1.3em; cursor: pointer;
        color: var(--color-text-main); border-bottom: 3px solid transparent;
        transition: color 0.3s, border-color 0.3s;
    }
    .cr-tab.active { color: var(--color-gold); border-bottom-color: var(--color-gold); }
    .cr-panel { display: none; padding: 20px; overflow-y: auto; flex-grow: 1;}
    .cr-panel.active { display: block; }
    .cr-panel::-webkit-scrollbar { width: 6px; }
    .cr-panel::-webkit-scrollbar-track { background: transparent; }
    .cr-panel::-webkit-scrollbar-thumb { background: var(--color-border); border-radius: 3px; }
    .technique-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(150px, 1fr)); gap: 15px; }
    .technique-tag {
        background: rgba(255,255,255,0.05); border: 1px solid var(--color-border);
        border-radius: 4px; padding: 10px; text-align: center; font-family: var(--font-header);
        color: var(--color-text-main); transition: all 0.3s;
    }
    .technique-tag:hover { background: rgba(230, 195, 132, 0.1); color: var(--color-gold); transform: translateY(-3px); }
    .cr-rumor-list { list-style: none; padding: 0; margin: 0; }
    .cr-rumor-list li {
        padding: 1em; margin-bottom: 1em; border-left: 3px solid var(--color-border);
        background: rgba(255, 255, 255, 0.03); border-radius: 0 4px 4px 0;
        font-style: italic; color: var(--color-text-main); font-size: 1.1em;
    }
    /* ===== CHARACTER RECORD UI REDESIGN END ===== */

    .settings-section { margin-bottom: 1.5rem; }
    .settings-row { display: flex; align-items: center; margin-bottom: 1rem; }
    .settings-row label { width: 80px; font-family: var(--font-header); color: var(--color-text-light); }
    .volume-slider { width: 100%; -webkit-appearance: none; appearance: none; height: 5px; background: var(--color-jade-dark); outline: none; border-radius: 5px; }
    .volume-slider::-webkit-slider-thumb { -webkit-appearance: none; appearance: none; width: 20px; height: 20px; background: var(--color-text-light); border: 2px solid var(--color-gold); border-radius: 50%; cursor: pointer; box-shadow: 0 0 5px var(--color-gold); }
    .volume-slider::-moz-range-thumb { width: 20px; height: 20px; background: var(--color-text-light); border: 2px solid var(--color-gold); border-radius: 50%; cursor: pointer; box-shadow: 0 0 5px var(--color-gold); }
</style>
</head>
<body>

<div id="data-source-content" style="display:none;">$1</div>
<div id="data-source-statusbar" style="display:none;">$2</div>

<div id="app-root">
    <!-- Content will be injected by script -->
</div>

<script>
(function() {
    const appRoot = document.getElementById('app-root');
    if (!appRoot) return;

    const tempContainer = document.createElement('div');
    const appHtml = `
        <audio id="sfx-left-click" src="https://files.catbox.moe/ixfqze.mp3" preload="auto"></audio>
        <audio id="sfx-right-click" src="https://files.catbox.moe/5gxx6o.mp3" preload="auto"></audio>
        <audio id="bgm-player" loop></audio>

        <div id="epic-map-container">
            <img id="map-background-image" src="https://files.catbox.moe/2eofkq.png" alt="玄寰仙途地图">
            <div class="map-content-wrapper">
                <svg id="map-paths-svg"></svg>
                <div class="map-nodes-container"></div>
                <div id="hud-overlay">
                    <div id="hud-time" class="hud-element"></div>
                    <div id="hud-location" class="hud-element"></div>
                    <div id="fullscreen-btn" class="hud-element">
                        <svg viewBox="0 0 24 24"><path d="M7 14H5v5h5v-2H7v-3zm-2-4h2V7h3V5H5v5zm12 7h-3v2h5v-5h-2v3zM14 5v2h3v3h2V5h-5z"/></svg>
                    </div>
                </div>
            </div>
        </div>

        <div id="galgame-container">
            <div id="galgame-bg"></div>
            <div id="galgame-sprites"><img id="sprite-left" class="galgame-sprite" alt=""><img id="sprite-right" class="galgame-sprite" alt=""></div>
            <div id="dialogue-box"><div id="speaker-name"></div><div id="dialogue-text"></div></div>
            <div id="galgame-ui-controls">
                <div id="galgame-prev-btn" class="galgame-ui-button" title="上一句">◄</div>
                <div id="galgame-autoplay-btn" class="galgame-ui-button" title="自动">▶</div>
                <div id="galgame-fullscreen-btn" class="galgame-ui-button" title="全屏">⛶</div>
            </div>
            <div id="galgame-history-log"></div>
        </div>

        <div id="main-menu-modal" class="modal-overlay">
            <div class="astrolabe-container">
                <div class="celestial-glyphs"></div>
                <div class="temporal-index"></div>
                <div class="taijitu-core"></div>
                <div class="menu-items-container">
                    <div class="main-menu-item" data-action="show-galgame">入世观景</div>
                    <div class="main-menu-item" data-modal="gacha-modal">天命祈愿</div>
                    <div class="main-menu-item" data-modal="character-modal">修行录</div>
                    <div class="main-menu-item" data-modal="inventory-modal">乾坤袋</div>
                    <div class="main-menu-item" data-modal="companions-fullscreen-modal">仙缘录</div>
                    <div class="main-menu-item" data-modal="tianji-modal">万法阁</div>
                </div>
            </div>
        </div>

        <div id="character-modal" class="modal-overlay"><div class="modal-content"><div class="modal-header"><span>修行录</span><span class="modal-close">&times;</span></div><div id="character-body" class="modal-body"></div></div></div>
        <div id="inventory-modal" class="modal-overlay"><div class="modal-content"><div id="inventory-body" class="modal-body"></div></div></div>
        <div id="companions-fullscreen-modal" class="modal-overlay"><div class="modal-content"><div id="companions-body" class="modal-body"></div></div></div>
        <div id="companion-bag-modal" class="modal-overlay"><div class="modal-content"><div class="modal-header"><span id="companion-bag-title"></span><span class="modal-close">&times;</span></div><div id="companion-bag-body" class="modal-body"></div></div></div>
        <div id="gacha-modal" class="modal-overlay"><div class="modal-content"><div id="gacha-body" class="modal-body"></div></div></div>

        <div id="tianji-modal" class="modal-overlay">
            <div class="modal-content">
                <div class="modal-header"><span>万法阁</span><span class="modal-close">&times;</span></div>
                <div class="modal-body">
                    <div id="settings-panel" class="tianji-panel active">
                        <div class="settings-section">
                            <h3>玄音</h3>
                            <div class="settings-row">
                                <label for="volume-slider">音量:</label>
                                <input type="range" id="volume-slider" class="volume-slider" min="0" max="1" step="0.01">
                            </div>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    `;
    tempContainer.innerHTML = appHtml;
    while (tempContainer.firstChild) {
        appRoot.appendChild(tempContainer.firstChild);
    }

    const App = {
        xmlDoc: null,
        init() {
            try {
                const narrativeData = document.getElementById('data-source-content').innerHTML;
                const statusBarData = `<root>${document.getElementById('data-source-statusbar').innerHTML}</root>`;
                this.xmlDoc = new DOMParser().parseFromString(statusBarData, "text/xml");
                if (this.xmlDoc.querySelector("parsererror")) { throw new Error("状态栏数据解析失败"); }

                this.renderHUD();
                this.setupEventListeners();

                AudioModule.init(); 
                MapModule.init();
                GalgameModule.init(narrativeData);
                InventoryModule.init();
                CompanionsModule.init();
                CharacterModule.init();
                TianjiModule.init();
                SettingsModule.init();
                GachaModule.init();
                MenuModule.init();

            } catch (error) { console.error("扩展初始化失败:", error); appRoot.innerHTML = `<div style="color: #ff7979; padding: 20px; background: #2f2f2f; border-radius: 8px;"><h3>扩展加载失败</h3><p>请按 F12 查看控制台。</p><pre style="white-space: pre-wrap; color: #f0e6d2;">${error.stack}</pre></div>`; }
        },
        getValue: function(selector, context = this.xmlDoc) { return context.querySelector(selector)?.textContent.trim() || null; },
        renderHUD() {
            const timeString = this.getValue('time') || '时辰未知';
            document.getElementById('hud-time').textContent = timeString;
            document.getElementById('hud-location').textContent = this.getValue('location') || '不知身在何处';
            MapModule.updateBackground(timeString);
        },
        setupEventListeners() {
            const fullscreenBtn = document.getElementById('fullscreen-btn');
            if (fullscreenBtn) { fullscreenBtn.addEventListener('click', (e) => { e.stopPropagation(); if (!document.fullscreenElement) { appRoot.requestFullscreen?.(); } else { document.exitFullscreen?.(); } }); }
             document.querySelectorAll('.modal-overlay:not(#companions-fullscreen-modal):not(#gacha-modal)').forEach(modal => {
                modal.addEventListener('click', function(e) { 
                    if (e.target === this) {
                        this.classList.remove('visible');
                        document.getElementById('epic-map-container')?.classList.remove('dimmed');
                    }
                });
                modal.querySelector('.modal-close')?.addEventListener('click', () => {
                    modal.classList.remove('visible');
                     document.getElementById('epic-map-container')?.classList.remove('dimmed');
                });
            });
        }
    };

    const AudioModule = {
        bgmPlayer: null, sfxLeft: null, sfxRight: null,
        playlist: [ 'https://files.catbox.moe/j373sb.mp3', 'https://files.catbox.moe/ket1fa.mp3', 'https://files.catbox.moe/fcs6fh.mp3' ],
        isMusicStarted: false,
        init() {
            this.bgmPlayer = document.getElementById('bgm-player');
            this.sfxLeft = document.getElementById('sfx-left-click');
            this.sfxRight = document.getElementById('sfx-right-click');
            const savedVolume = parseFloat(localStorage.getItem('xuanhuan_volume'));
            this.setVolume(isNaN(savedVolume) ? 0.5 : savedVolume);
            document.body.addEventListener('click', () => this.playSound('left'), {capture: true});
            document.body.addEventListener('contextmenu', () => this.playSound('right'), { capture: true });
            this.bgmPlayer.addEventListener('ended', () => this.playRandom());
            this.startMusic();
        },
        startMusic() {
            if (this.isMusicStarted || !this.bgmPlayer) return;
            this.playRandom();
            const promise = this.bgmPlayer.play();
            if (promise !== undefined) {
                promise.then(() => { this.isMusicStarted = true; })
                .catch(error => {
                    console.warn("BGM autoplay was blocked. Waiting for user interaction.");
                    const startOnInteraction = () => {
                        this.bgmPlayer.play().then(() => {
                            this.isMusicStarted = true;
                            document.removeEventListener('click', startOnInteraction, true);
                        }).catch(err => console.error("Could not start music on interaction:", err));
                    };
                    document.addEventListener('click', startOnInteraction, true);
                });
            }
        },
        playRandom() {
            if (this.playlist.length === 0) return;
            const randomIndex = Math.floor(Math.random() * this.playlist.length);
            const nextTrack = this.playlist[randomIndex];
            if (this.bgmPlayer.src !== nextTrack) { this.bgmPlayer.src = nextTrack; }
            if(this.isMusicStarted) this.bgmPlayer.play().catch(e => console.error("BGM play failed after track ended:", e));
        },
        playSound(type) {
            const sound = (type === 'left') ? this.sfxLeft : this.sfxRight;
            if (sound) { sound.currentTime = 0; sound.play().catch(e => {}); }
        },
        setVolume(level) {
            if (this.bgmPlayer) this.bgmPlayer.volume = level;
            if (this.sfxLeft) this.sfxLeft.volume = level;
            if (this.sfxRight) this.sfxRight.volume = level;
        }
    };

    const MenuModule = {
        init() {
            const mainMenu = document.getElementById('main-menu-modal');
            const menuContainer = mainMenu.querySelector('.menu-items-container');
            const menuItems = mainMenu.querySelectorAll('.main-menu-item');
            const mapContainer = document.getElementById('epic-map-container');
            const showMenu = (e) => { if (document.querySelector('#galgame-container.visible')) return; e.preventDefault(); mainMenu.classList.add('visible'); mapContainer.classList.add('dimmed'); };
            mapContainer.addEventListener('contextmenu', showMenu);
            let pressTimer = null;
            mapContainer.addEventListener('touchstart', e => { pressTimer = setTimeout(() => showMenu(e), 500); }, { passive: true });
            mapContainer.addEventListener('touchend', () => clearTimeout(pressTimer));
            mapContainer.addEventListener('touchmove', () => clearTimeout(pressTimer));
            menuItems.forEach(item => {
                item.addEventListener('mouseenter', e => {
                    const rect = item.getBoundingClientRect(); const menuRect = menuContainer.getBoundingClientRect();
                    const x = e.clientX - menuRect.left; const y = e.clientY - menuRect.top;
                    menuContainer.style.setProperty('--hover-light-pos-x', `${x}px`);
                    menuContainer.style.setProperty('--hover-light-pos-y', `${y}px`);
                    menuContainer.style.setProperty('--hover-light-opacity', '1');
                });
                item.addEventListener('click', e => {
                    e.stopPropagation();
                    const modalId = item.dataset.modal; const action = item.dataset.action;
                    if (modalId) {
                        const modal = document.getElementById(modalId);
                        if(modal) {
                           if (modalId === 'inventory-modal') InventoryModule.render();
                           if (modalId === 'companions-fullscreen-modal') CompanionsModule.render();
                           if (modalId === 'character-modal') CharacterModule.render();
                           if (modalId === 'tianji-modal') TianjiModule.render();
                           if (modalId === 'gacha-modal') GachaModule.render();
                           modal.classList.add('visible');
                        }
                    } else if (action === 'show-galgame') { GalgameModule.show(); }
                    mainMenu.classList.remove('visible');
                    mapContainer.classList.remove('dimmed');
                });
            });
            menuContainer.addEventListener('mouseleave', () => { menuContainer.style.setProperty('--hover-light-opacity', '0'); });
            this.generateRunes();
        },
        generateRunes() {
            const container = document.querySelector('.celestial-glyphs'); if (!container) return;
            const runes = ['☰','☱','☲','☳','☴','☵','☶','☷']; const radius = 46;
            runes.forEach((rune, i) => {
                const angle = (i / runes.length) * 2 * Math.PI; const x = 50 + radius * Math.cos(angle); const y = 50 + radius * Math.sin(angle);
                const runeEl = document.createElement('span'); runeEl.className = 'rune-symbol'; runeEl.textContent = rune;
                runeEl.style.left = `${x}%`; runeEl.style.top = `${y}%`;
                runeEl.style.transform = `translate(-50%, -50%) rotate(${angle * (180/Math.PI) + 90}deg)`;
                container.appendChild(runeEl);
            });
        }
    };

