        init() {
            const nodesContainer = document.querySelector('.map-nodes-container');
            nodesContainer.innerHTML = '';
            for (const name in this.nodeCoordinates) {
                const node = document.createElement('div');
                const simpleName = name.split(/·| /).pop();
                let category = 'neutral';
                const matchedKey = Object.keys(this.locationCategories).find(key => name.includes(key));
                if (matchedKey) { category = this.locationCategories[matchedKey]; }
                node.className = `map-node node-${category}`;
                node.style.left = `${this.nodeCoordinates[name][0]}%`;
                node.style.top = `${this.nodeCoordinates[name][1]}%`;
                node.dataset.name = name;
                node.innerHTML = `<div class="node-tooltip">${simpleName}</div>`;
                nodesContainer.appendChild(node);
            }
            const locationString = App.getValue('location');
            if (locationString) {
                const locationParts = locationString.split('/').map(s => s.trim()).reverse();
                let currentLocationName = null;
                const nodeKeys = Object.keys(this.nodeCoordinates);

                for (const part of locationParts) {
                    if (!part) continue;
                    let bestMatch = null;
                    let longestMatchLength = 0;
                    for (const key of nodeKeys) {
                        const simpleKey = key.split(/·| /).pop();
                        if (simpleKey && part.includes(simpleKey)) {
                            if (simpleKey.length > longestMatchLength) {
                                bestMatch = key;
                                longestMatchLength = simpleKey.length;
                            }
                        }
                    }
                    if (bestMatch) {
                        currentLocationName = bestMatch;
                        break;
                    }
                }

                if (currentLocationName) {
                    const currentNode = nodesContainer.querySelector(`[data-name="${currentLocationName}"]`);
                    if(currentNode) currentNode.classList.add('current-location');
                }
            }
            this.drawPaths();
        },
        drawPaths() {
            const svg = document.getElementById('map-paths-svg');
            svg.innerHTML = '';
            this.pathConnections.forEach(([start, end]) => {
                if (this.nodeCoordinates[start] && this.nodeCoordinates[end]) {
                    const line = document.createElementNS('http://www.w3.org/2000/svg', 'line');
                    line.setAttribute('x1', `${this.nodeCoordinates[start][0]}%`); line.setAttribute('y1', `${this.nodeCoordinates[start][1]}%`);
                    line.setAttribute('x2', `${this.nodeCoordinates[end][0]}%`); line.setAttribute('y2', `${this.nodeCoordinates[end][1]}%`);
                    line.className = 'path-line'; svg.appendChild(line);
                }
            });
        },
        updateBackground(timeString) {
            const nightHours = ['戌', '亥', '子', '丑', '寅'];
            const match = timeString.match(/(子|丑|寅|卯|辰|巳|午|未|申|酉|戌|亥)时/);
            const currentHour = match ? match[1] : null;
            const bgImage = document.getElementById('map-background-image');
            if (!bgImage) return;

            if (currentHour && nightHours.includes(currentHour)) {
                if (bgImage.src !== this.nightBackground) { bgImage.src = this.nightBackground; }
            } else {
                if (bgImage.src !== this.dayBackground) { bgImage.src = this.dayBackground; }
            }
        }
