        toggleHistoryLog() { const isVisible = this.elements.historyLog.classList.toggle('visible'); if (isVisible) { if (this.state.isAutoPlaying) this.toggleAutoPlay(); let historyHtml = ''; const pastDialogues = this.state.dialogueLines.slice(0, this.state.currentIndex + 1); pastDialogues.forEach(line => { const content = line.speaker === '旁白' ? line.text : `「${line.text}」`; historyHtml += `<div class="history-entry"><div class="history-speaker">${line.speaker}</div><div class="history-text">${content}</div></div>`; }); this.elements.historyLog.innerHTML = historyHtml; this.elements.historyLog.scrollTop = this.elements.historyLog.scrollHeight; } },
        toggleFullscreen() { const appContainer = document.getElementById('app-root'); if (!document.fullscreenElement) { appContainer.requestFullscreen?.(); } else { document.exitFullscreen?.(); } }
