        padding: 1em; margin-bottom: 1em; border-left: 3px solid var(--color-border);
        background: rgba(255, 255, 255, 0.03); border-radius: 0 4px 4px 0;
        font-style: italic; color: var(--color-text-main); font-size: 1.1em;
    }
    /* ===== CHARACTER RECORD UI REDESIGN END ===== */

    .settings-section { margin-bottom: 1.5rem; }
    .settings-row { display: flex; align-items: center; margin-bottom: 1rem; }
    .settings-row label { width: 80px; font-family: var(--font-header); color: var(--color-text-light); }
    .volume-slider { width: 100%; -webkit-appearance: none; appearance: none; height: 5px; background: var(--color-jade-dark); outline: none; border-radius: 5px; }
    .volume-slider::-webkit-slider-thumb { -webkit-appearance: none; appearance: none; width: 20px; height: 20px; background: var(--color-text-light); border: 2px solid var(--color-gold); border-radius: 50%; cursor: pointer; box-shadow: 0 0 5px var(--color-gold); }
    .volume-slider::-moz-range-thumb { width: 20px; height: 20px; background: var(--color-text-light); border: 2px solid var(--color-gold); border-radius: 50%; cursor: pointer; box-shadow: 0 0 5px var(--color-gold); }
</style>
