<body>

<div id="data-source-content" style="display:none;">$1</div>
<div id="data-source-statusbar" style="display:none;">$2</div>

<div id="app-root">
    <!-- Content will be injected by script -->
</div>

<script>
(function() {
    const appRoot = document.getElementById('app-root');
    if (!appRoot) return;

    const tempContainer = document.createElement('div');
    const appHtml = `
        <audio id="sfx-left-click" src="https://files.catbox.moe/ixfqze.mp3" preload="auto"></audio>
        <audio id="sfx-right-click" src="https://files.catbox.moe/5gxx6o.mp3" preload="auto"></audio>
        <audio id="bgm-player" loop></audio>

        <div id="epic-map-container">
            <img id="map-background-image" src="https://files.catbox.moe/2eofkq.png" alt="玄寰仙途地图">
