                    </div>
                </div>
            </div>
        </div>

        <div id="galgame-container">
            <div id="galgame-bg"></div>
            <div id="galgame-sprites"><img id="sprite-left" class="galgame-sprite" alt=""><img id="sprite-right" class="galgame-sprite" alt=""></div>
            <div id="dialogue-box"><div id="speaker-name"></div><div id="dialogue-text"></div></div>
            <div id="galgame-ui-controls">
                <div id="galgame-prev-btn" class="galgame-ui-button" title="上一句">◄</div>
                <div id="galgame-autoplay-btn" class="galgame-ui-button" title="自动">▶</div>
                <div id="galgame-fullscreen-btn" class="galgame-ui-button" title="全屏">⛶</div>
            </div>
            <div id="galgame-history-log"></div>
        </div>

        <div id="main-menu-modal" class="modal-overlay">
            <div class="astrolabe-container">
                <div class="celestial-glyphs"></div>
                <div class="temporal-index"></div>
                <div class="taijitu-core"></div>
                <div class="menu-items-container">
                    <div class="main-menu-item" data-action="show-galgame">入世观景</div>
                    <div class="main-menu-item" data-modal="gacha-modal">天命祈愿</div>
                    <div class="main-menu-item" data-modal="character-modal">修行录</div>
                    <div class="main-menu-item" data-modal="inventory-modal">乾坤袋</div>
                    <div class="main-menu-item" data-modal="companions-fullscreen-modal">仙缘录</div>
                    <div class="main-menu-item" data-modal="tianji-modal">万法阁</div>
                </div>
            </div>
        </div>

        <div id="character-modal" class="modal-overlay"><div class="modal-content"><div class="modal-header"><span>修行录</span><span class="modal-close">&times;</span></div><div id="character-body" class="modal-body"></div></div></div>
        <div id="inventory-modal" class="modal-overlay"><div class="modal-content"><div id="inventory-body" class="modal-body"></div></div></div>
        <div id="companions-fullscreen-modal" class="modal-overlay"><div class="modal-content"><div id="companions-body" class="modal-body"></div></div></div>
        <div id="companion-bag-modal" class="modal-overlay"><div class="modal-content"><div class="modal-header"><span id="companion-bag-title"></span><span class="modal-close">&times;</span></div><div id="companion-bag-body" class="modal-body"></div></div></div>
        <div id="gacha-modal" class="modal-overlay"><div class="modal-content"><div id="gacha-body" class="modal-body"></div></div></div>

        <div id="tianji-modal" class="modal-overlay">
            <div class="modal-content">
                <div class="modal-header"><span>万法阁</span><span class="modal-close">&times;</span></div>
                <div class="modal-body">
                    <div id="settings-panel" class="tianji-panel active">
                        <div class="settings-section">
                            <h3>玄音</h3>
                            <div class="settings-row">
                                <label for="volume-slider">音量:</label>
                                <input type="range" id="volume-slider" class="volume-slider" min="0" max="1" step="0.01">
                            </div>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    `;
    tempContainer.innerHTML = appHtml;
    while (tempContainer.firstChild) {
        appRoot.appendChild(tempContainer.firstChild);
    }

    const App = {
        xmlDoc: null,
        init() {
            try {
                const narrativeData = document.getElementById('data-source-content').innerHTML;
                const statusBarData = `<root>${document.getElementById('data-source-statusbar').innerHTML}</root>`;
                this.xmlDoc = new DOMParser().parseFromString(statusBarData, "text/xml");
                if (this.xmlDoc.querySelector("parsererror")) { throw new Error("状态栏数据解析失败"); }

                this.renderHUD();
                this.setupEventListeners();

                AudioModule.init(); 
                MapModule.init();
                GalgameModule.init(narrativeData);
                InventoryModule.init();
                CompanionsModule.init();
                CharacterModule.init();
                TianjiModule.init();
                SettingsModule.init();
                GachaModule.init();
                MenuModule.init();

            } catch (error) { console.error("扩展初始化失败:", error); appRoot.innerHTML = `<div style="color: #ff7979; padding: 20px; background: #2f2f2f; border-radius: 8px;"><h3>扩展加载失败</h3><p>请按 F12 查看控制台。</p><pre style="white-space: pre-wrap; color: #f0e6d2;">${error.stack}</pre></div>`; }
        },
        getValue: function(selector, context = this.xmlDoc) { return context.querySelector(selector)?.textContent.trim() || null; },
        renderHUD() {
            const timeString = this.getValue('time') || '时辰未知';
            document.getElementById('hud-time').textContent = timeString;
            document.getElementById('hud-location').textContent = this.getValue('location') || '不知身在何处';
            MapModule.updateBackground(timeString);
        },
        setupEventListeners() {
            const fullscreenBtn = document.getElementById('fullscreen-btn');
            if (fullscreenBtn) { fullscreenBtn.addEventListener('click', (e) => { e.stopPropagation(); if (!document.fullscreenElement) { appRoot.requestFullscreen?.(); } else { document.exitFullscreen?.(); } }); }
             document.querySelectorAll('.modal-overlay:not(#companions-fullscreen-modal):not(#gacha-modal)').forEach(modal => {
                modal.addEventListener('click', function(e) { 
                    if (e.target === this) {
                        this.classList.remove('visible');
                        document.getElementById('epic-map-container')?.classList.remove('dimmed');
                    }
                });
                modal.querySelector('.modal-close')?.addEventListener('click', () => {
                    modal.classList.remove('visible');
                     document.getElementById('epic-map-container')?.classList.remove('dimmed');
                });
            });
        }
    };

    const AudioModule = {
        bgmPlayer: null, sfxLeft: null, sfxRight: null,
        playlist: [ 'https://files.catbox.moe/j373sb.mp3', 'https://files.catbox.moe/ket1fa.mp3', 'https://files.catbox.moe/fcs6fh.mp3' ],
        isMusicStarted: false,
        init() {
            this.bgmPlayer = document.getElementById('bgm-player');
            this.sfxLeft = document.getElementById('sfx-left-click');
            this.sfxRight = document.getElementById('sfx-right-click');
            const savedVolume = parseFloat(localStorage.getItem('xuanhuan_volume'));
            this.setVolume(isNaN(savedVolume) ? 0.5 : savedVolume);
            document.body.addEventListener('click', () => this.playSound('left'), {capture: true});
            document.body.addEventListener('contextmenu', () => this.playSound('right'), { capture: true });
            this.bgmPlayer.addEventListener('ended', () => this.playRandom());
            this.startMusic();
        },
        startMusic() {
            if (this.isMusicStarted || !this.bgmPlayer) return;
            this.playRandom();
            const promise = this.bgmPlayer.play();
            if (promise !== undefined) {
                promise.then(() => { this.isMusicStarted = true; })
                .catch(error => {
                    console.warn("BGM autoplay was blocked. Waiting for user interaction.");
                    const startOnInteraction = () => {
                        this.bgmPlayer.play().then(() => {
                            this.isMusicStarted = true;
                            document.removeEventListener('click', startOnInteraction, true);
                        }).catch(err => console.error("Could not start music on interaction:", err));
                    };
                    document.addEventListener('click', startOnInteraction, true);
                });
            }
        },
        playRandom() {
            if (this.playlist.length === 0) return;
            const randomIndex = Math.floor(Math.random() * this.playlist.length);
            const nextTrack = this.playlist[randomIndex];
            if (this.bgmPlayer.src !== nextTrack) { this.bgmPlayer.src = nextTrack; }
            if(this.isMusicStarted) this.bgmPlayer.play().catch(e => console.error("BGM play failed after track ended:", e));
        },
        playSound(type) {
            const sound = (type === 'left') ? this.sfxLeft : this.sfxRight;
            if (sound) { sound.currentTime = 0; sound.play().catch(e => {}); }
        },
        setVolume(level) {
            if (this.bgmPlayer) this.bgmPlayer.volume = level;
            if (this.sfxLeft) this.sfxLeft.volume = level;
            if (this.sfxRight) this.sfxRight.volume = level;
        }
    };

    const MenuModule = {
        init() {
            const mainMenu = document.getElementById('main-menu-modal');
            const menuContainer = mainMenu.querySelector('.menu-items-container');
            const menuItems = mainMenu.querySelectorAll('.main-menu-item');
            const mapContainer = document.getElementById('epic-map-container');
            const showMenu = (e) => { if (document.querySelector('#galgame-container.visible')) return; e.preventDefault(); mainMenu.classList.add('visible'); mapContainer.classList.add('dimmed'); };
            mapContainer.addEventListener('contextmenu', showMenu);
            let pressTimer = null;
            mapContainer.addEventListener('touchstart', e => { pressTimer = setTimeout(() => showMenu(e), 500); }, { passive: true });
            mapContainer.addEventListener('touchend', () => clearTimeout(pressTimer));
            mapContainer.addEventListener('touchmove', () => clearTimeout(pressTimer));
            menuItems.forEach(item => {
                item.addEventListener('mouseenter', e => {
                    const rect = item.getBoundingClientRect(); const menuRect = menuContainer.getBoundingClientRect();
                    const x = e.clientX - menuRect.left; const y = e.clientY - menuRect.top;
                    menuContainer.style.setProperty('--hover-light-pos-x', `${x}px`);
                    menuContainer.style.setProperty('--hover-light-pos-y', `${y}px`);
                    menuContainer.style.setProperty('--hover-light-opacity', '1');
                });
                item.addEventListener('click', e => {
                    e.stopPropagation();
                    const modalId = item.dataset.modal; const action = item.dataset.action;
                    if (modalId) {
                        const modal = document.getElementById(modalId);
                        if(modal) {
                           if (modalId === 'inventory-modal') InventoryModule.render();
                           if (modalId === 'companions-fullscreen-modal') CompanionsModule.render();
                           if (modalId === 'character-modal') CharacterModule.render();
                           if (modalId === 'tianji-modal') TianjiModule.render();
                           if (modalId === 'gacha-modal') GachaModule.render();
                           modal.classList.add('visible');
                        }
                    } else if (action === 'show-galgame') { GalgameModule.show(); }
                    mainMenu.classList.remove('visible');
                    mapContainer.classList.remove('dimmed');
                });
            });
            menuContainer.addEventListener('mouseleave', () => { menuContainer.style.setProperty('--hover-light-opacity', '0'); });
            this.generateRunes();
        },
        generateRunes() {
            const container = document.querySelector('.celestial-glyphs'); if (!container) return;
            const runes = ['☰','☱','☲','☳','☴','☵','☶','☷']; const radius = 46;
            runes.forEach((rune, i) => {
                const angle = (i / runes.length) * 2 * Math.PI; const x = 50 + radius * Math.cos(angle); const y = 50 + radius * Math.sin(angle);
                const runeEl = document.createElement('span'); runeEl.className = 'rune-symbol'; runeEl.textContent = rune;
                runeEl.style.left = `${x}%`; runeEl.style.top = `${y}%`;
                runeEl.style.transform = `translate(-50%, -50%) rotate(${angle * (180/Math.PI) + 90}deg)`;
                container.appendChild(runeEl);
            });
        }
    };

