                modal.classList.remove('visible'); 
                document.getElementById('epic-map-container')?.classList.remove('dimmed');
            }); 
        },

        switchCompanion(index) {
            if (index === this._currentIndex || this._isSwitching || !this._data[index]) return;

            this._isSwitching = true;
            this._currentIndex = index;

            const companion = this._data[index];
            const { portraitContainer, infoName, infoAffection, infoCultivation, infoStatus, bagButton, selectorList, affectionFill } = this._elements;

            infoName.textContent = companion.name;
            infoAffection.querySelector('.affection-value').textContent = companion.affection;
            infoCultivation.querySelector('span').textContent = companion.cultivation;
            infoStatus.querySelector('span').textContent = companion.status;
            bagButton.dataset.name = companion.name;
            bagButton.dataset.bag = companion.bag;
            bagButton.disabled = !companion.bag;
            bagButton.textContent = companion.bag ? '查看行囊' : '行囊为空';

            const affectionValue = parseInt(companion.affection, 10) || 0;
            const affectionPercent = Math.max(0, Math.min(100, (affectionValue + 100) / 2));
            affectionFill.style.width = affectionPercent + '%';

            const activeSelector = selectorList.querySelector('.active');
            if (activeSelector) activeSelector.classList.remove('active');
            const newActiveSelector = selectorList.querySelector(`[data-index="${index}"]`);
            if (newActiveSelector) newActiveSelector.classList.add('active');

            const oldPortrait = portraitContainer.querySelector('.companion-main-portrait');
            if (oldPortrait) {
                oldPortrait.className = 'companion-main-portrait portrait-outgoing';
                setTimeout(() => oldPortrait.remove(), 500);
            }

            const incomingPortrait = document.createElement('img');
            incomingPortrait.src = companion.portraitUrl;
            incomingPortrait.className = 'companion-main-portrait portrait-incoming';
            portraitContainer.appendChild(incomingPortrait);

            setTimeout(() => { this._isSwitching = false; }, 500);
        },

        render() { 
            const body = document.getElementById('companions-body'); 
            const companions = App.xmlDoc.querySelectorAll('companion'); 

            if (companions.length === 0) { 
                body.innerHTML = `<div class="companion-viewer"><div id="companion-viewer-bg"></div><p style="position:absolute; top:50%; left:50%; transform:translate(-50%, -50%); color:var(--color-text-main); font-size: 1.5em; z-index:10;">道途漫漫，孤身一人。</p></div>`; 
                return; 
            } 

            body.innerHTML = `
                <div class="companion-viewer">
                    <div id="companion-viewer-bg"></div>
                    <div id="companion-portrait-container"></div>
                    <div id="companion-info-panel">
                        <h2 id="companion-info-name"></h2>
                        <div id="info-line-affection" class="info-line">
                            <strong><span class="heart-icon">❤</span> 心缘:</strong> 
                            <div class="affection-progress-container">
                                <div id="affection-progress-fill" class="affection-progress-fill"></div>
                            </div>
                            <span class="affection-value"></span>
                        </div>
                        <div id="info-line-cultivation" class="info-line"><strong>☯ 境界:</strong> <span></span></div>
                        <div id="info-line-status" class="info-line"><strong>◎ 状态:</strong> <span></span></div>
                        <button id="companion-bag-btn-viewer"></button>
                    </div>
                    <div id="companion-selector-scroll">
                        <div id="companion-selector-list"></div>
                    </div>
                    <div id="companion-viewer-fullscreen-btn" title="全屏/退出全屏">⛶</div>
                </div>
            `;

            this._elements = {
                portraitContainer: document.getElementById('companion-portrait-container'),
                infoName: document.getElementById('companion-info-name'),
                infoAffection: document.getElementById('info-line-affection'),
                affectionFill: document.getElementById('affection-progress-fill'),
                infoCultivation: document.getElementById('info-line-cultivation'),
                infoStatus: document.getElementById('info-line-status'),
                bagButton: document.getElementById('companion-bag-btn-viewer'),
                selectorList: document.getElementById('companion-selector-list'),
                fullscreenBtn: document.getElementById('companion-viewer-fullscreen-btn')
            };

            this._data = Array.from(companions).map((c, index) => ({
                name: App.getValue('name', c) || '未知',
                bag: App.getValue('bag', c) || '', 
                affection: App.getValue('affection', c) || '0', 
                status: App.getValue('status', c) || '未知', 
                cultivation: App.getValue('cultivation', c) || '凡人',
                portraitUrl: GalgameModule.getSpriteUrl(App.getValue('name', c)) || 'https://files.catbox.moe/g65f96.png'
            }));

            const selectorHtml = this._data.map((c, index) => {
                const avatarUrl = c.portraitUrl;
                return `<div class="companion-selector-item" data-index="${index}"><img src="${avatarUrl}" alt="${c.name}"></div>`;
            }).join('');

            this._elements.selectorList.innerHTML = selectorHtml;

            this._elements.selectorList.addEventListener('click', e => {
                const item = e.target.closest('.companion-selector-item');
                if (item) {
                    const index = parseInt(item.dataset.index, 10);
                    this.switchCompanion(index);
                }
            });

            this._elements.bagButton.addEventListener('click', e => { 
                e.stopPropagation(); 
                InventoryModule.showCompanionBag(e.target.dataset.name, e.target.dataset.bag); 
            });

            this._elements.fullscreenBtn.addEventListener('click', e => {
                e.stopPropagation();
                GalgameModule.toggleFullscreen();
            });

            this._currentIndex = -1;
            this.switchCompanion(0);
        }
    };

    // ===== INVENTORY MODULE MODIFIED =====
    const InventoryModule = {
        init() {
            const companionBagModal = document.getElementById('companion-bag-modal');
            companionBagModal.querySelector('.modal-close').addEventListener('click', () => {
                companionBagModal.classList.remove('visible');
            });
            companionBagModal.addEventListener('click', function(e){
                if (e.target === this) this.classList.remove('visible');
            });
        },
        render() { 
            const body = document.getElementById('inventory-body'); 
            const points = App.getValue('points') || 0; 
            const stones = App.getValue('stones') || '上品:0, 中品:0, 下品:0'; 
            const stonesFormatted = stones.replace(/上品灵石:/g, '💎').replace(/中品灵石:/g, '💠').replace(/下品灵石:/g, '🔸'); 

            body.innerHTML = `
                <div class="inventory-stardust-bg"></div>
                <div id="inventory-header-re">
                    <span class="points">⚡ 震惊点: ${points}</span>
                    <span>${stonesFormatted}</span>
                </div>
                <div class="item-grid-container">
                    <div class="item-grid"></div>
                </div>
                <p class="inventory-empty-msg" style="display: none;">空空如也</p>
            `;

            const inventory = App.getValue('inventory'); 
            const grid = body.querySelector('.item-grid');
            const emptyMsg = body.querySelector('.inventory-empty-msg');

            if (inventory && inventory.trim() !== '') { 
                emptyMsg.style.display = 'none';
                grid.innerHTML = inventory.split('、').map((item, index) => {
                    const itemName = item.trim();
                    return `<div class="inventory-card-re" style="animation-delay: ${index * 0.05}s;">
                        <div class="item-card-icon">${this.getIconForItem(itemName)}</div>
                        <div class="item-card-name">${itemName}</div>
                    </div>`;
                }).join('');
            } else {
                emptyMsg.style.display = 'block';
                grid.innerHTML = '';
            }
        },
        showCompanionBag(name, bagContent) { 
            const modal = document.getElementById('companion-bag-modal'); 
            modal.querySelector('#companion-bag-title').textContent = `${name}的行囊`; 
            const body = modal.querySelector('#companion-bag-body');

            body.innerHTML = `
                <div class="inventory-stardust-bg"></div>
                <div class="item-grid-container">
                    <div class="item-grid"></div>
                </div>
                <p class="inventory-empty-msg" style="display: none;">行囊空空如也。</p>
            `;

            const grid = body.querySelector('.item-grid');
            const emptyMsg = body.querySelector('.inventory-empty-msg');

            if (bagContent && bagContent.trim() !== '') { 
                emptyMsg.style.display = 'none';
                grid.innerHTML = bagContent.split('、').map((item, index) => {
                    const itemName = item.trim();
                    return `<div class="inventory-card-re" style="animation-delay: ${index * 0.05}s;">
                        <div class="item-card-icon">${this.getIconForItem(itemName)}</div>
                        <div class="item-card-name">${itemName}</div>
                    </div>`;
                }).join('');
            } else {
                emptyMsg.style.display = 'block';
                grid.innerHTML = '';
            }

            modal.classList.add('visible'); 
        },
        getIconForItem(name) {
            if (/剑|刀|枪|斧|戟|幡|印|钟|塔|镜|轮|弓|刃|宝|珠|尺|剪|绫|圈|扇/.test(name)) return '⚔️';
            if (/甲|铠|袍|衣|带|冠|靴|佩|环/.test(name)) return '🛡️';
            if (/丹|药|丸|散|膏/.test(name)) return '💊';
            if (/草|花|果|木|芝|根|藤|叶|菌|灵/.test(name)) return '🌿';
            if (/法|诀|经|录|典|图|卷|纸|报|术/.test(name)) return '📜';
            if (/石|晶|玉|铁|金|沙|矿|骨|鳞|羽|血|核|魂/.test(name)) return '💎';
            if (/水|液|泉|酒|露|乳|浆/.test(name)) return '💧';
            if (/符|箓|咒/.test(name)) return '🔖';
            if (/钥|牌|令/.test(name)) return '🗝️';
            if (/肉|粮|饼/.test(name)) return '🍖';
            return '📦';
        }
    };

    const CharacterModule = {
        init() {},
        render() {
            const body = document.getElementById('character-body');
            const cultivation = App.getValue('cultivation') || '凡人';
            const techniques = App.getValue('techniques');
            const rumors = App.getValue('rumors');

            const realmList = [
                { key: '凡人', name: '凡人', colorClass: 'realm-fanren' },
                { key: '炼气', name: '炼气境', colorClass: 'realm-lianqi' },
                { key: '筑基', name: '筑基境', colorClass: 'realm-zhuji' },
                { key: '金丹', name: '金丹境', colorClass: 'realm-jindan' },
                { key: '元婴', name: '元婴境', colorClass: 'realm-yuanying' },
                { key: '化神', name: '化神境', colorClass: 'realm-huashen' },
                { key: '返虚', name: '返虚境', colorClass: 'realm-fanxu' },
                { key: '合道', name: '合道境', colorClass: 'realm-hedao' },
                { key: '大乘', name: '大乘境', colorClass: 'realm-dacheng' },
                { key: '渡劫', name: '渡劫境', colorClass: 'realm-dujie' },
                { key: '仙', name: '仙人之境', colorClass: 'realm-xian' }
            ];

            let currentIndex = 0;
            for (let i = realmList.length - 1; i >= 0; i--) {
                if (cultivation.includes(realmList[i].key)) {
                    currentIndex = i;
                    break;
                }
            }

            const cultivationPathHtml = realmList.map((realm, index) => {
                let stateClass = 'future-realm';
                if (index < currentIndex) stateClass = 'past-realm';
                if (index === currentIndex) stateClass = 'current-realm';
                return `<div class="realm-card ${stateClass} ${realm.colorClass}">
                            <h3>${realm.name}</h3>
                            ${index === currentIndex ? `<p>${cultivation}</p>` : ''}
                        </div>`;
            }).join('');

            const techniquesHtml = (techniques && techniques.trim() !== '') 
                ? `<div class="technique-grid">${techniques.split('、').map(t => `<div class="technique-tag">${t.trim()}</div>`).join('')}</div>`
                : '<p>未习得任何功法</p>';

            const rumorsHtml = (rumors && rumors.trim() !== '')
                ? `<ul class="cr-rumor-list">${rumors.split(/[\n;；]/).map(r => r.trim()).filter(r => r).map(r => `<li>${r}</li>`).join('')}</ul>`
                : '<p>天下太平，暂无风闻。</p>';

            body.innerHTML = `
                <div class="cultivation-record-layout">
                    <div id="cultivation-path">${cultivationPathHtml}</div>
                    <div id="dao-records">
                        <div class="cr-tabs">
                            <div class="cr-tab active" data-panel="techniques-panel">已习功法</div>
                            <div class="cr-tab" data-panel="rumors-panel">世间风闻</div>
                        </div>
                        <div id="techniques-panel" class="cr-panel active">${techniquesHtml}</div>
                        <div id="rumors-panel" class="cr-panel">${rumorsHtml}</div>
                    </div>
                </div>
            `;

            // Add event listeners for the new tabs
            const tabs = body.querySelectorAll('.cr-tab');
            const panels = body.querySelectorAll('.cr-panel');
            tabs.forEach(tab => {
                tab.addEventListener('click', () => {
                    tabs.forEach(t => t.classList.remove('active'));
                    panels.forEach(p => p.classList.remove('active'));
                    tab.classList.add('active');
                    body.querySelector(`#${tab.dataset.panel}`).classList.add('active');
                });
            });

            // Scroll current realm into view
            setTimeout(() => {
                const currentRealmEl = body.querySelector('.current-realm');
                if (currentRealmEl) {
                    currentRealmEl.scrollIntoView({ behavior: 'smooth', block: 'center' });
                }
            }, 100);
        }
    };

    const TianjiModule = {
        init() {}, // No listeners needed as it's just one panel now
        render() {
            // This module now only renders the settings panel, which is static HTML.
            // So, this render function is effectively empty but kept for structure.
        }
    };

    const SettingsModule = {
        init() {
            const volumeSlider = document.getElementById('volume-slider');
            if (!volumeSlider) return;
            const savedVolume = localStorage.getItem('xuanhuan_volume');
            const initialVolume = (savedVolume !== null) ? parseFloat(savedVolume) : 0.5;
            volumeSlider.value = initialVolume;
            volumeSlider.addEventListener('input', (e) => {
                const newVolume = parseFloat(e.target.value);
                AudioModule.setVolume(newVolume);
                localStorage.setItem('xuanhuan_volume', newVolume);
            });
        }
    };

    // ===== GACHA MODULE ADDED =====
    const GachaModule = {
