                modal.classList.remove('visible'); 
                document.getElementById('epic-map-container')?.classList.remove('dimmed');
            }); 
        },
        render() {
            const body = document.getElementById('gacha-body');
            const limitCharacterName = App.getValue('limit');

            let activeHtml = '';
            let inactiveHtml = `<div id="gacha-inactive-banner" class="visible"><h2 id="gacha-no-event-text">当前没有活动</h2></div>`;

            if (limitCharacterName && limitCharacterName.trim() !== '') {
                const characterName = limitCharacterName.trim();
                const portraitUrl = GalgameModule.getSpriteUrl(characterName) || 'https://files.catbox.moe/g65f96.png'; // Fallback

                activeHtml = `
