    function adjustForLandscapeFullscreen() { const appRoot = document.getElementById('app-root'); const viewportHeight = window.innerHeight; const viewportWidth = window.innerWidth; const targetRatio = 16 / 9; const viewportRatio = viewportWidth / viewportHeight; let containerWidth, containerHeight; if (viewportRatio > targetRatio) { containerHeight = viewportHeight; containerWidth = containerHeight * targetRatio; } else { containerWidth = viewportWidth; containerHeight = containerWidth / targetRatio; } appRoot.style.cssText = `position: fixed !important; top: 50% !important; left: 50% !important; width: ${containerWidth}px !important; height: ${containerHeight}px !important; transform: translate(-50%, -50%) !important; padding: 0 !important;`; }
    function resetStyles() { document.getElementById('app-root').style.cssText = ''; }
    if(window.screen && window.screen.orientation) { window.screen.orientation.addEventListener('change', function() { if (isInFullscreen) { setTimeout(handleFullscreenChange, 100); } }); }
